INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('73lwR7JKHA4QzyIl2P2E', 'Tiramisu', 'Italský klasický dezert, který zažene špatnou náladu.', 0, 'dezerty', '2020-01-12', 'recipes/73lwR7JKHA4QzyIl2P2E-main.jpg', 'Tiramisu – hotový pokrm', 4, 20, 'Snadné');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 0, 'amaretto', 'amaretta', 5, 'cl');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 1, 'cukr-krupice', 'krupicového cukru', 2, 'lžíce');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 2, 'kakao', 'kakaa', 1, 'lžíce');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 3, 'kava', 'zrnkové mleté kávy', 1, 'lžička');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 4, 'vejce', 'vejce', 2, '');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 5, 'cukrarske-piskoty', 'cukrářských piškotů', 12, '');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('73lwR7JKHA4QzyIl2P2E', 6, 'mascarpone', 'mascarpone', 250, 'g');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('73lwR7JKHA4QzyIl2P2E', 0, 'Uvaříme si malý hrnek kávy a přidáme do něj amaretto.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('73lwR7JKHA4QzyIl2P2E', 1, 'Žloutky si vyšleháme s cukrem, poté zašleháme mascarpone a nakonec zlehka vmícháme ušlehaný sníh z bílků.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('73lwR7JKHA4QzyIl2P2E', 2, 'Připravíme si čtyři nízké skleničky. A namáčíme piškoty do kávy s likérem tak, aby nasákly tekutinu, ale nebyly příliš rozmočené a vložíme je na dno skleniček. Na piškoty rozetřeme polovinu krému a na krém opět namočené piškoty a další vrstvu krému, kterou posypeme kakaem.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('73lwR7JKHA4QzyIl2P2E', 3, 'Skleničky uložíme aspoň na 2 hodiny do lednice.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('73lwR7JKHA4QzyIl2P2E', 4, 'Recept obsahuje syrová vejce, proto je dobré mít vejce co nejčerstvější.', 1, NULL, NULL);
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('73lwR7JKHA4QzyIl2P2E', 'Itálie');
INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('7uDf27jmYF8R2AjVwqfR', 'Krutonky', 'Krutonky si můžeme vyrobit z jakéhokoliv pečiva, které máme rádi, nejlépe den dva starého, prostě z toho, které nám zbylo. Někdo má rád krutonky v polévce jen na ozdobu a někdo jich sní celou misku. A tím se stane z polévky hlavní chod.', 0, 'dezerty', '2018-02-20', 'recipes/7uDf27jmYF8R2AjVwqfR-main.jpg', 'Krutonky – hotový pokrm', 2, 15, 'Snadné');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('7uDf27jmYF8R2AjVwqfR', 0, 'chleba', 'chleba', 4, 'krajíce');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('7uDf27jmYF8R2AjVwqfR', 1, 'cesnek', 'česneku', 1, 'stroužek');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('7uDf27jmYF8R2AjVwqfR', 2, 'susena-petrzel', 'sušené petrželky', 1, 'lžička');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('7uDf27jmYF8R2AjVwqfR', 0, 'Krutonky můžeme připravit dopředu a schovat do suché vzduchotěsné nádoby.', 1, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('7uDf27jmYF8R2AjVwqfR', 1, 'Pečivo pokrájíme na středně velké kostičky.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('7uDf27jmYF8R2AjVwqfR', 2, 'Osmahneme na středně rozpálené grilovací nebo obyčejné pánvi na sucho spolu se stroužkem česneku, který jsme neoloupali a sušenou petrželkou. Průběžně prohazujeme/promícháváme.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('7uDf27jmYF8R2AjVwqfR', 3, 'Krutonky lze také upéct v troubě (190°, 10min), kde dojde k rovnoměrnému opečení a stačí promíchat jen jednou, v polovině době pečení.', 1, NULL, NULL);
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('7uDf27jmYF8R2AjVwqfR', 'bio');
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('7uDf27jmYF8R2AjVwqfR', 'light');
INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('Kd202PmJmbCufFELxLCA', 'Italské houbové rizoto', 'Krémové italské rizoto pro chmurné dny.', 0, 'dezerty', '2018-02-17', 'recipes/Kd202PmJmbCufFELxLCA-main.jpg', 'Italské houbové rizoto – hotový pokrm', 4, 50, 'Snadné');
