INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('Kd202PmJmbCufFELxLCA', 9, 'susene-houby', 'sušených hub', 0.5, 'hrnku');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('Kd202PmJmbCufFELxLCA', 10, 'tymian', 'sušeneho tymiánu', 1, 'lzicka');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('Kd202PmJmbCufFELxLCA', 0, 'Sušené houby namočíme do teplé vody. A na troše olivového oleje osmahneme omyté a nakrájené žampiony a šalotku nakrájenou na jemno.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('Kd202PmJmbCufFELxLCA', 1, 'Cuketu zbavíme slupky, nakrájíme na malé kostičky a přidáme do pánve, osolíme, opepříme a okořeníme tymiánem.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('Kd202PmJmbCufFELxLCA', 2, 'Dále přidáme rýži a promícháme. Vhodíme bujón a 2 hrnky vody. Vodu přidáváme postupně (celkem cca 1l). Do pánve přilijeme i vodu ze sušených hub a přidáme sušené houby.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('Kd202PmJmbCufFELxLCA', 3, 'Ke konci vaření přidáme mražený hrášek. Poté parmezán a ještě lehce prohřejeme, ale už nevaříme.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('Kd202PmJmbCufFELxLCA', 4, 'Ihned podáváme posypané parmezánem.', 0, NULL, NULL);
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('Kd202PmJmbCufFELxLCA', 'bio');
INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('ZcWqZjnIW81zafRQ41DG', 'Salát se sýrem brie', 'Jemný sýr brie v kombinaci s lehce kyselými jablky, křupavými ořechy, čerstvým salátem a medovou zálivkou je ideální na rychlý oběd.', 1, 'saláty', '2020-01-27', 'recipes/ZcWqZjnIW81zafRQ41DG-main.jpg', 'Salát se sýrem brie – hotový pokrm', 2, 15, 'Snadné');
INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('gSdIeyNxhVffc2aO2cAf', 'Perník s meruňkovou marmeládou', 'Vůně perníkového koření provoní domov a v kombinaci s meruňkovou marmeládou je perník ideální k odpolední kávě či čaji.', 1, 'dezerty', '2020-04-04', 'recipes/gSdIeyNxhVffc2aO2cAf-main.jpg', 'Perník s meruňkovou marmeládou – hotový pokrm', 24, 60, 'Snadné');
INSERT INTO recipes (id, title, description, draft, category, published, image_key, image_alt, serves, minutes, difficulty) VALUES ('jpscnE6PuIduHCLLdJnU', 'Špagety Carbonara', 'Italská klasika, která nikdy nezklame.', 0, 'hlavní chody', '2020-01-12', 'recipes/jpscnE6PuIduHCLLdJnU-main.jpg', 'Špagety Carbonara – hotový pokrm', 4, 20, 'Snadné');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('jpscnE6PuIduHCLLdJnU', 0, 'slanina', 'slaniny', 150, 'g');
INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('jpscnE6PuIduHCLLdJnU', 1, 'spagety', 'špaget', 500, 'g');
