INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('jpscnE6PuIduHCLLdJnU', 5, 'cedar', 'čedaru', 150, 'g');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('jpscnE6PuIduHCLLdJnU', 0, 'Dáme vařit vodu na špagety. A mezitím si orestujeme slaninu nakrájenou na kostičky na troše olivového oleje.', 0, 'recipes/jpscnE6PuIduHCLLdJnU-step-1.jpg', 'Špagety Carbonara – postup, krok 1');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('jpscnE6PuIduHCLLdJnU', 1, 'Dáme vařit špagety. Do misky si nastrouháme čedar a čtvrtinu si odložíme stranou. K sýru přidáme rozklepnutá vejce, pepř, trochu soli a rozmícháme.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('jpscnE6PuIduHCLLdJnU', 2, 'Uvařené špagety slijeme, ale necháme si hrnek vody stranou. Ke špagetám přidáme směs vajec a sýru a polovinu hrnku vody. Mícháním se vytvoří lehká omáčka, která obalí špagety. Podle konzistence případně přilijeme ještě vodu ze špaget.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('jpscnE6PuIduHCLLdJnU', 3, 'Dále přidáme slaninu, zamícháme a ihned podáváme posypané zbylým čedarem.', 0, NULL, NULL);
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('jpscnE6PuIduHCLLdJnU', 'Itálie');
