INSERT INTO recipe_ingredients (recipe_id, position, ingredient_id, display_name, quantity, unit) VALUES ('mmRswzC4uecNEoia0MH6', 9, 'cukr', 'třtinového cukru', NULL, 'hrnku');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 0, 'Na vodní lázni si rozpustíme 120g čokolády s máslem.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 1, 'Čokoládu a máslo můžeme rozpustit i v mikrovlnce. Dáme ho do ní na 30s, vyndáme, zamícháme a znovu ho tam vložíme na 20s a podle potřeby opakujeme, dokud není čokoláda s máslem rozpuštěná. Dáváme pozor, aby se nám čokoláda nespálila.', 1, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 2, 'Troubu si předehřejeme na 200°C.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 3, 'Nejdříve si v míse smícháme mouku, cukr, prášek do pečiva a kakao, uděláme důlek a přidáme jogurt, vejce a vychladlou rozpuštěnou čokoládu s máslem.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 4, 'Nakonec zlehka vmícháme vypeckované višně a zbytek čokolády pokrájené na kousky.', 0, NULL, NULL);
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 5, 'Směsí naplníme muffinovou formu vyloženou papírovými košíčky.', 0, 'recipes/mmRswzC4uecNEoia0MH6-step-6.jpg', 'Čokoládové muffiny s višněmi – postup, krok 6');
INSERT INTO recipe_steps (recipe_id, position, content, tip, image_key, image_alt) VALUES ('mmRswzC4uecNEoia0MH6', 6, 'Pečeme 30min na 180°C.', 0, NULL, NULL);
INSERT INTO recipe_tags (recipe_id, tag) VALUES ('mmRswzC4uecNEoia0MH6', 'čokoláda');
